    if isNull data || not (data.StartsWith("0xa20479c6", StringComparison.OrdinalIgnoreCase)) then invalidArg "data" "Custom error selector mismatch"
    if data.Length <> 10 then invalidArg "data" "Unexpected custom error payload"
    Nethereum.Contracts.Error(typeof<BackingLotNotFoundError>).DecodeExceptionEncodedData<BackingLotNotFoundError>(data)

